const props = __props;
const emit = __emit;

const saving = ref(false);
const message = reactive({ show: false, type: 'info', text: '' });
const form = reactive({
  enabled: true,
  source_url: 'https://savept.icu/',
  request_timeout: 15,
  default_internal_only: false,
  notify: true,
  cron: '0 8 * * *',
  use_proxy: true,
  use_browser_emulation: false,
  ...props.initialConfig,
});
let messageTimer = null;

function clearMessageTimer() {
  if (messageTimer) {
    clearTimeout(messageTimer);
    messageTimer = null;
  }
}

function scheduleMessageClose(type = 'info') {
  clearMessageTimer();
  const timeout = type === 'error' ? 5000 : 3000;
  messageTimer = setTimeout(() => {
    message.show = false;
    messageTimer = null;
  }, timeout);
}

function pushMessage(text, type = 'info') {
  message.text = text;
  message.type = type;
  message.show = true;
  scheduleMessageClose(type);
}

async function saveConfig() {
  saving.value = true;
  try {
    const result = await pluginRequest(props.api, '/config', {
      method: 'POST',
      body: {
        enabled: !!form.enabled,
        source_url: form.source_url,
        request_timeout: Number(form.request_timeout || 15),
        default_internal_only: !!form.default_internal_only,
        notify: !!form.notify,
        cron: form.cron,
        use_proxy: !!form.use_proxy,
        use_browser_emulation: !!form.use_browser_emulation,
      },
    });
    if (!result?.success) {
      throw new Error(result?.message || '保存失败')
    }
    pushMessage('配置已保存', 'success');
  } catch (error) {
    pushMessage(error.message || '保存失败', 'error');
  } finally {
    saving.value = false;
  }
}

onBeforeUnmount(() => {
  clearMessageTimer();
});

